using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using Forms=System.Windows.Forms;
public static class DesignReview {
 public static void Seed(MonitorWindow window){var now=DateTime.UtcNow;window.History.Clear();for(int i=0;i<=60;i++)window.History.Add(new ResourceSample{Time=now.AddSeconds((i-60)*5),Cpu=31+19*Math.Sin(i/5.2)+8*Math.Sin(i/1.9),Memory=38+i*.12,Download=1048576*(18+9*Math.Sin(i/7.0)),Upload=1048576*(4+3*Math.Sin(i/4.0)),Storage=37.8+i*.004});}

 public static int Demo(string folder){Directory.CreateDirectory(folder);var window=new MonitorWindow(true);try{var demo=Storage.DefaultServer();demo.Name="compute-node";demo.Host="10.0.0.8";window.CompactOptions.Servers.Clear();window.ChooseServer(demo);var sample=Program.Fixture("eight");foreach(var process in sample.Processes){process.Name="/workspace/train.py";process.User="researcher";}Seed(window);window.SetMetrics(sample,false);window.SwitchView("GPU");foreach(var theme in new[]{"graphite","forest"}){window.ApplyAppearance(theme);window.RenderImage(Path.Combine(folder,"demo-"+theme+".png"),1440,1000,144);}return 0;}finally{window.Exit();}}
 public static int Run(string folder){Directory.CreateDirectory(folder);var window=new MonitorWindow(true);try{Seed(window);var sample=Program.Fixture("eight");sample.Hardware=new HardwareInfo{CpuModel="Intel(R) Xeon(R) Gold 6338 CPU @ 2.00GHz",PhysicalSockets=2,PhysicalCores=64,SystemThreads=128,AvailableThreads=124,MemoryBytes=1024L*1024*1024*1024,Note="Synthetic UI fixture"};window.SetMetrics(sample,false);foreach(var page in new[]{"CPU","GPU","内存","网络","存储"}){window.SwitchView(page);window.RenderImage(Path.Combine(folder,page+".png"),1440,900,120);}window.SwitchView("CPU");window.SelectResourceTab("cores");window.RenderImage(Path.Combine(folder,"cpu-cores.png"),1440,900,120);window.SelectResourceTab("hardware");window.RenderImage(Path.Combine(folder,"cpu-hardware.png"),1440,900,120);var editor=new SettingsWindow(window.CompactOptions.Copy(),true);editor.RenderImage(Path.Combine(folder,"settings.png"),960,800,120);for(int page=1;page<4;page++){editor.SelectSettingsPage(page);editor.RenderImage(Path.Combine(folder,"settings-"+page+".png"),960,800,120);}new AboutWindow(null,null).Render(Path.Combine(folder,"about.png"));
 var trayMethod=typeof(MonitorWindow).GetMethod("InitTray",BindingFlags.Instance|BindingFlags.NonPublic);trayMethod.Invoke(window,null);var tray=(Forms.NotifyIcon)typeof(MonitorWindow).GetField("tray",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);var menu=tray.ContextMenuStrip;if(menu!=null){menu.PerformLayout();using(var bmp=new System.Drawing.Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(bmp,new System.Drawing.Rectangle(System.Drawing.Point.Empty,menu.Size));bmp.Save(Path.Combine(folder,"tray-before.png"),System.Drawing.Imaging.ImageFormat.Png);}}
 new TrayFlyout("aq-server",()=>{},()=>{},()=>{},()=>{},()=>{},()=>true,value=>{}).Render(Path.Combine(folder,"tray-after.png"));return 0;}finally{window.Exit();}}
}
